// Generates the brand modules consumed at runtime from the resolved brand:
//   - src/branding.generated.ts   (renderer / Vite / TS)
//   - electron/branding.generated.cjs (electron main process, CommonJS)
//
// Run automatically before dev/build (see package.json). Re-run when you
// change BRAND or edit a branding/*.json file.
//
// The generated files are git-ignored — they are derived artifacts.

const fs = require('node:fs')
const path = require('node:path')
const { resolveBrand } = require('../branding/brand.cjs')

const ROOT = path.join(__dirname, '..')

function main() {
  const brand = resolveBrand()
  const json = JSON.stringify(brand, null, 2)
  const banner = `// AUTO-GENERATED by scripts/gen-branding.cjs from branding/${brand.id}.json.\n// Do not edit by hand. Run \`npm run gen:branding\` (or any build) to refresh.\n`

  // Renderer (TypeScript, typed against the Brand interface).
  const tsPath = path.join(ROOT, 'src', 'branding.generated.ts')
  const ts = `${banner}import type { Brand } from '../branding/types'\n\nexport const BRAND: Brand = ${json}\n`
  fs.writeFileSync(tsPath, ts)

  // Electron main (CommonJS).
  const cjsPath = path.join(ROOT, 'electron', 'branding.generated.cjs')
  const cjs = `${banner}module.exports = ${json}\n`
  fs.writeFileSync(cjsPath, cjs)

  // eslint-disable-next-line no-console
  console.log(`[branding] generated for "${brand.productName}" (${brand.id}) → ${brand.appId}`)
}

main()
